    72|
    73|const COMMENT_MARKERS: Array<{ marker: string; severity: DebtSeverity; why: string }> = [
    74|  { marker: 'FIXME', severity: 'high', why: 'Flagged broken/needs-fixing code left in place.' },
    75|  { marker: 'HACK', severity: 'high', why: 'Acknowledged workaround that should be replaced with a real solution.' },
