   164|/** Pure: oversized-file finding for a given LOC, or null if within budget. */
   165|export function classifyOversizedFile(relativePath: string, loc: number): DebtFinding | null {
   166|  if (loc < OVERSIZED_WARN_LOC) return null;
   167|  const severity: DebtSeverity = loc >= OVERSIZED_HIGH_LOC ? 'high' : 'low';
   168|  return {
   169|    kind: 'oversized_file',
   170|    marker: 'oversized-file',
   171|    severity,
   172|    relativePath,
   173|    line: 0,
   174|    snippet: `${loc} lines of code`,
   175|    why: `File is ${loc} LOC (≥ ${loc >= OVERSIZED_HIGH_LOC ? OVERSIZED_HIGH_LOC : OVERSIZED_WARN_LOC}) — large modules are harder to reason about and safely change.`,
   176|  };
   177|}
   178|
   179|const SEVERITY_RANK: Record<DebtSeverity, number> = { critical: 0, high: 1, medium: 2, low: 3 };
   180|
   181|function sortFindings(a: DebtFinding, b: DebtFinding): number {
   182|  const sev = SEVERITY_RANK[a.severity] - SEVERITY_RANK[b.severity];
   183|  if (sev !== 0) return sev;
   184|  const p = a.relativePath.localeCompare(b.relativePath);
   185|  if (p !== 0) return p;
   186|  return a.line - b.line;
