   189|async function walkSourceFiles(dir: string, root: string, out: string[]): Promise<void> {
   190|  let entries: Dirent[];
   191|  try {
   192|    entries = (await readdir(dir, { withFileTypes: true })) as unknown as Dirent[];
   193|  } catch {
   194|    return;
   195|  }
   196|  for (const entry of entries) {
   197|    if (entry.name.startsWith('.') && entry.name !== '.') {
   198|      // skip dotfiles/dotdirs except explicit allowed ones (none here)
   199|      if (IGNORE_DIRS.has(entry.name)) continue;
   200|    }
   201|    const full = path.join(dir, entry.name);
   202|    if (entry.isDirectory()) {
   203|      if (IGNORE_DIRS.has(entry.name)) continue;
   204|      await walkSourceFiles(full, root, out);
   205|      continue;
   206|    }
   207|    if (!entry.isFile()) continue;
   208|    const ext = path.extname(entry.name);
   209|    if (!SCAN_EXTS.has(ext)) continue;
   210|    if (entry.name.endsWith('.d.ts')) continue;
   211|    out.push(full);
   212|  }
   213|}
