   215|/**
   216| * Walk the workspace and produce a full technical-debt + freeze-risk report.
   217| * `rootOverride` makes the walker testable against a fixture directory.
   218| */
   219|export async function scanWorkspaceForTechDebt(options?: { rootOverride?: string }): Promise<TechDebtReport> {
   220|  const start = Date.now();
   221|  const root = options?.rootOverride ?? SERVER_ROOT;
   222|  const files: string[] = [];
   223|  await walkSourceFiles(root, root, files);
   224|
   225|  const findings: DebtFinding[] = [];
   226|  let filesScanned = 0;
   227|
   228|  for (const file of files) {
   229|    let bytes = 0;
   230|    try {
   231|      const info = await stat(file);
   232|      bytes = info.size;
   233|    } catch {
   234|      continue;
   235|    }
   236|    if (bytes > MAX_FILE_BYTES) continue;
   237|
   238|    let content = '';
   239|    try {
   240|      content = await readFile(file, 'utf8');
   241|    } catch {
   242|      continue;
   243|    }
   244|    filesScanned += 1;
   245|    const relativePath = path.relative(root, file);
   246|    findings.push(...scanContentForDebt(relativePath, content));
   247|    const loc = content.length === 0 ? 0 : content.split(/\r?\n/).length;
   248|    const oversized = classifyOversizedFile(relativePath, loc);
   249|    if (oversized) findings.push(oversized);
   250|  }
   251|
   252|  findings.sort(sortFindings);
   253|
   254|  const bySeverity: Record<DebtSeverity, number> = { critical: 0, high: 0, medium: 0, low: 0 };
   255|  let debtMarkers = 0;
   256|  let freezeRisks = 0;
   257|  let oversizedFiles = 0;
   258|  for (const f of findings) {
   259|    bySeverity[f.severity] += 1;
   260|    if (f.kind === 'debt_marker') debtMarkers += 1;
   261|    else if (f.kind === 'freeze_risk') freezeRisks += 1;
