   268|    root,
   269|    durationMs: Date.now() - start,
   270|    filesScanned,
   271|    totals: { findings: findings.length, debtMarkers, freezeRisks, oversizedFiles },
   272|    bySeverity,
   273|    findings,
   274|  };
